using Optimus.Core;
using System.Text.Json;
var tests = new List<(string Name, Action Run)>();
void Test(string name, Action run) => tests.Add((name,run));
void Check(bool condition, string behavior) { if(!condition) throw new Exception(behavior); }
var context = new BrowserContext(Guid.NewGuid(), 1, "https://example.org");
Test("URL: bare domains use HTTPS", () => Check(NavigationPolicy.Resolve("example.org/path", SearchProvider.DuckDuckGo).Uri?.AbsoluteUri == "https://example.org/path", "Expected HTTPS bare domain"));
Test("URL: ordinary search uses selected fixed provider", () => { var r=NavigationPolicy.Resolve("ayuntamiento de Madrid", SearchProvider.Google); Check(r.IsSearch && r.Uri?.Host=="www.google.com" && r.Uri.Query.Contains("ayuntamiento"),"Expected fixed Google search"); });
Test("URL: unsafe and attempted schemes never become searches", () => { foreach(var s in new[]{"file:///c:/secret","javascript:alert(1)","data:text/html,hello","mailto:a@b.com","custom:payload","https:example.org","https://user:pass@example.org","https://example.org/\nsecret","https://","https://example.org\\evil","https://exa mple.org"}) Check(!NavigationPolicy.Resolve(s,SearchProvider.Google).Allowed,"Rejected "+s); });
Test("URL: explicit HTTP remains ordinary navigation", () => Check(NavigationPolicy.Resolve("http://localhost:8080", SearchProvider.Google) is {Allowed:true,IsSearch:false},"Expected HTTP"));
Test("Actions: confirmation is exact-once", () => { var store=new ProposalStore(new TestClock()); var p=store.Propose(new(ActionKind.BookmarkCurrent), context); Check(store.TryConsume(p.Id,context,out var a)&&a?.Kind==ActionKind.BookmarkCurrent,"First confirmation must succeed"); Check(!store.TryConsume(p.Id,context,out _),"Duplicate must fail"); });
Test("Actions: expiry occurs at exactly 60 seconds", () => { var clock=new TestClock(); var store=new ProposalStore(clock); var p=store.Propose(new(ActionKind.BookmarkCurrent),context); Check(p.ExpiresAt-clock.GetUtcNow()==TimeSpan.FromSeconds(60),"TTL must be 60 seconds"); clock.Advance(60); Check(!store.TryConsume(p.Id,context,out _),"Expired proposal rejected"); });
Test("Actions: 59 seconds remains confirmable", () => { var c=new TestClock();var s=new ProposalStore(c);var p=s.Propose(new(ActionKind.BookmarkCurrent),context);c.Advance(59);Check(s.TryConsume(p.Id,context,out _),"Before expiry succeeds"); });
Test("Actions: stale tab document and origin consume nothing", () => { foreach(var wrong in new[]{context with {TabId=Guid.NewGuid()},context with {DocumentVersion=2},context with {Origin="https://evil.org"}}) { var s=new ProposalStore(new TestClock());var p=s.Propose(new(ActionKind.BookmarkCurrent),context);Check(!s.TryConsume(p.Id,wrong,out _),"Wrong context rejected"); Check(!s.TryConsume(p.Id,context,out _),"Mismatch revokes stale action"); } });
Test("Actions: cancel revokes every pending proposal", () => { var s=new ProposalStore(new TestClock());var p=s.Propose(new(ActionKind.BookmarkCurrent),context);s.RevokeAll();Check(!s.TryConsume(p.Id,context,out _),"Canceled rejected"); });
Test("Actions: unsafe bounded values never become proposals", () => { foreach(var a in new[]{new AssistantAction(ActionKind.OpenUrl,"javascript:alert(1)"),new(ActionKind.SetTextScale,"20"),new(ActionKind.SetContrast,"maybe"),(new AssistantAction((ActionKind)99))}) { bool rejected=false;try { new ProposalStore(new TestClock()).Propose(a,context); } catch(ArgumentException) {rejected=true;} Check(rejected,"Invalid action rejected"); } });
Test("Sharing: attribution contains only origin", () => { var r=SharedExcerpt.Create("hola",new Uri("https://example.org:8443/private?q=secret#password"));Check(r.Origin=="https://example.org:8443" && r.Text=="hola" && r.Error==null,"Origin only"); });
Test("Sharing: 8000 UTF16 characters with explicit truncation notice", () => {var r=SharedExcerpt.Create(new string('x',8001),new Uri("https://example.org"));Check(r.Text.Length==8000 && r.WasTruncated && r.Error==null,"Truncation must be signaled");var exact=SharedExcerpt.Create(new string('x',8000),new Uri("https://example.org"));Check(!exact.WasTruncated,"Exact limit accepted"); });
Test("Sharing: invalid origins and empty text give clear errors", () => {Check(SharedExcerpt.Create("",new Uri("https://example.org")).Error!=null,"Empty text rejected");Check(SharedExcerpt.Create("x",new Uri("file:///secret")).Error!=null,"Local source rejected"); });
Test("Guide: honest labelled local guidance only proposes navigation", () => {var r=LocalGuide.Respond("abre https://example.org",context);Check(r.Text.Contains("Guía local basada en reglas") && r.Action==new AssistantAction(ActionKind.OpenUrl,"https://example.org/"),"Label and normalized proposal");Check(LocalGuide.Respond("paga mi factura",context).Action==null,"Unsupported intent cannot execute");});
Test("Guide: bookmark zoom and permissions explain or propose bounded changes", () => {Check(LocalGuide.Respond("guardar marcador",context).Action?.Kind==ActionKind.BookmarkCurrent,"Bookmark proposal");Check(LocalGuide.Respond("aumentar zoom",context).Action==new AssistantAction(ActionKind.SetTextScale,"1.25"),"Bounded zoom proposal");Check(LocalGuide.Respond("permiso cámara",context).Action==null,"Permissions cannot be granted by guide");});
Test("Settings: atomic roundtrip retains preferences and bookmarks", () => {var dir=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString());try {var s=new SettingsStore(Path.Combine(dir,"settings.json"));var b=new BrowserSettings {TextScale=1.5, HighContrast=true, RestoreSession=true, SessionUrls=["https://example.org"],Bookmarks=[new("Inicio","https://example.org")]};Check(s.Save(b)==null,"Save succeeds");var r=s.Load();Check(r.Error==null && r.Settings.HighContrast && r.Settings.TextScale==1.5 && r.Settings.Bookmarks.Count==1 && r.Settings.SessionUrls.Count==1,"Roundtrip values");}finally{if(Directory.Exists(dir))Directory.Delete(dir,true);}});
Test("Settings: corrupt data preserved and recovery error surfaced", () => {var dir=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString());Directory.CreateDirectory(dir);var path=Path.Combine(dir,"settings.json");try{File.WriteAllText(path,"{bad");var s=new SettingsStore(path);Check(s.Load().Error!=null,"Corrupt load reported");Check(File.ReadAllText(path)=="{bad","Original preserved");Check(s.Save(new())!=null && File.ReadAllText(path)=="{bad","Cannot silently overwrite corrupt data");}finally{Directory.Delete(dir,true);}});
Test("Settings: session URLs persist only after explicit opt-in", () => {var dir=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString());try{var s=new SettingsStore(Path.Combine(dir,"s.json"));Check(s.Save(new() {SessionUrls=["https://secret.example"]})==null,"Save succeeds");Check(s.Load().Settings.SessionUrls.Count==0,"Opt-out does not persist addresses");}finally{if(Directory.Exists(dir))Directory.Delete(dir,true);}});
Test("Official registry: exact hosts only and review older than 30 days expires", () => {var date=new DateOnly(2026,10,29);var r=new OfficialSiteRegistry([new("example.org",new Uri("https://institution.example/reference"),date.AddDays(-30))]);Check(r.Describe(new Uri("https://example.org/path?q=x"),date).StartsWith("Oficial ·"),"30 day review valid");Check(r.Describe(new Uri("https://evil.example.org"),date).Contains("sin verificar"),"Subdomains require their own entry");Check(r.Describe(new Uri("https://example.org.evil.test"),date).Contains("sin verificar"),"Suffix lookalike rejected");Check(r.Describe(new Uri("https://example.org"),date.AddDays(1)).Contains("pendiente"),"31 day review is stale");});
Test("Actions: simultaneous confirmations execute once", () => {var s=new ProposalStore(new TestClock());var p=s.Propose(new(ActionKind.BookmarkCurrent),context);int count=0;Parallel.For(0,20,_=>{if(s.TryConsume(p.Id,context,out var a))Interlocked.Increment(ref count);});Check(count==1,"Exactly one consumer wins");});
Test("Sharing: truncation never splits a surrogate pair", () => {var r=SharedExcerpt.Create(new string('x',7999)+"😀z",new Uri("https://example.org"));Check(r.WasTruncated&&r.Text.Length==7999&&!char.IsHighSurrogate(r.Text[^1]),"Unicode remains valid");});
Test("Settings: invalid persisted preferences are preserved as corruption", () => {var dir=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString());Directory.CreateDirectory(dir);var path=Path.Combine(dir,"s.json");try{File.WriteAllText(path,"{\"TextScale\":99}");var s=new SettingsStore(path);Check(s.Load().Error!=null&&s.Save(new())!=null,"Out of bounds settings cannot overwrite source");}finally{Directory.Delete(dir,true);}});
Test("Actions: clock rollback cannot extend the 60 second lifetime", () => {var clock=new TestClock();var s=new ProposalStore(clock);var p=s.Propose(new(ActionKind.BookmarkCurrent),context);clock.Advance(59);clock.RewindUtc(120);clock.Advance(1);Check(!s.TryConsume(p.Id,context,out _),"Monotonic deadline survives wall clock rollback");});
Test("Deferred prompts: posting never opens modal UI before callback returns", () => {var posted=new Queue<Action>();int shown=0,completed=0;var request=new DeferredRequest(()=>true,()=>shown++,()=>completed++,_=>{});request.Post(posted.Enqueue);Check(shown==0&&completed==0&&posted.Count==1,"Prompt must remain queued");posted.Dequeue()();Check(shown==1&&completed==1,"Posted prompt runs after return");});
Test("Deferred prompts: revoked request completes once without opening", () => {var posted=new Queue<Action>();int shown=0,completed=0;bool valid=true;var r=new DeferredRequest(()=>valid,()=>shown++,()=>completed++,_=>{});r.Post(posted.Enqueue);valid=false;r.Cancel();r.Cancel();while(posted.TryDequeue(out var run))run();Check(shown==0&&completed==1,"Revoked prompt never appears; deferral completed once");});
Test("Deferred prompts: exception and canceled dispatch complete exactly once", () => {int complete=0,fail=0;var r=new DeferredRequest(()=>true,()=>throw new IOException(),()=>complete++,_=>fail++);r.Post(a=>a());r.Cancel();Check(complete==1&&fail==1,"Exception completes once");});
Test("Lifecycle: destructive operation waits for creation and replacement executes", () => {var q=new AsyncOperationQueue();var creation=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);bool destroyed=false,replaced=false;var first=q.RunAsync(()=>creation.Task);var second=q.RunAsync(()=>{destroyed=true;replaced=true;return Task.CompletedTask;});Check(!destroyed,"Cannot dispose during creation await");creation.SetResult();Task.WhenAll(first,second).GetAwaiter().GetResult();Check(replaced,"Queued replacement is not lost");});
Test("Lifecycle: disposal cancels captured operation and stale continuation", () => {var l=new OperationLifetime();var token=l.Token;l.Dispose();bool rejected=false;try{l.Check();}catch(OperationCanceledException){rejected=true;}Check(token.IsCancellationRequested&&rejected,"Disposed work cannot resume");});
Test("Profile clear: timeout retains task and blocks every reuse after late completion", () => {var g=new ProfileOperationGate();var work=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);int safety=0;var ok=g.RunAsync(work.Task,()=>Interlocked.Increment(ref safety),TimeSpan.Zero).GetAwaiter().GetResult();Check(!ok&&g.IsBlocked&&g.RequiresRestart&&ReferenceEquals(g.UnderlyingTask,work.Task),"Timeout requires restart and retains actual task");work.SetResult();g.SettlementTask!.GetAwaiter().GetResult();Check(g.IsBlocked&&safety==1,"Late settlement reapplies safety and cannot reopen profile");});
Test("Profile clear: success restores policies before allowing navigation", () => {var g=new ProfileOperationGate();bool blockedAtRestore=false;Check(g.RunAsync(Task.CompletedTask,()=>blockedAtRestore=g.IsBlocked,TimeSpan.FromSeconds(1)).GetAwaiter().GetResult()&&blockedAtRestore&&!g.IsBlocked,"Safety precedes release");});
Test("Profile clear: fault requires restart and never opens profile", () => {var g=new ProfileOperationGate();Check(!g.RunAsync(Task.FromException(new IOException()),()=>{},TimeSpan.FromSeconds(1)).GetAwaiter().GetResult()&&g.IsBlocked&&g.RequiresRestart,"Fault stays blocked");});
Test("Bookmarks: failed save rolls back so retry really persists once", () => {var list=new List<Bookmark>();int saves=0;var b=new Bookmark("Inicio","https://example.org/");Check(BookmarkPersistence.TryAdd(list,b,()=>{saves++;return false;})==BookmarkSaveResult.Failed&&list.Count==0,"Failure rolls back unsaved bookmark");Check(BookmarkPersistence.TryAdd(list,b,()=>{saves++;return true;})==BookmarkSaveResult.Saved&&list.Count==1&&saves==2,"Retry must reach persistence");});
Test("Bookmarks: real disk error rolls back and recovery saves on retry", () => {var dir=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString());Directory.CreateDirectory(dir);var blocked=Path.Combine(dir,"profile");File.WriteAllText(blocked,"blocking directory creation");try{var settings=new BrowserSettings();var store=new SettingsStore(Path.Combine(blocked,"settings.json"));var b=new Bookmark("Inicio","https://example.org/");Check(BookmarkPersistence.TryAdd(settings.Bookmarks,b,()=>store.Save(settings)==null)==BookmarkSaveResult.Failed&&settings.Bookmarks.Count==0,"Disk failure cannot leave a duplicate");File.Delete(blocked);Check(BookmarkPersistence.TryAdd(settings.Bookmarks,b,()=>store.Save(settings)==null)==BookmarkSaveResult.Saved&&store.Load().Settings.Bookmarks.Count==1,"Retry after disk recovery persists one bookmark");}finally{Directory.Delete(dir,true);}});
Test("URL snapshot: fragment and SPA source changes replace the persisted address", () => {var snapshot=new NavigationSnapshot();snapshot.TryRefresh(()=>"https://example.org/start");snapshot.TryRefresh(()=>"https://example.org/start#paso-2");Check(snapshot.LastAddress=="https://example.org/start#paso-2","Fragment change must be restored");snapshot.TryRefresh(()=>"https://example.org/app/route?step=3#detalle");Check(snapshot.LastAddress=="https://example.org/app/route?step=3#detalle","SPA route/query/fragment must be current");});
Test("URL snapshot: blank invalid and failed native reads preserve the last valid URL", () => {var snapshot=new NavigationSnapshot();snapshot.TryRefresh(()=>"https://example.org/app#guardado");foreach(var source in new string?[]{null,"about:blank","file:///secret","javascript:alert(1)","https://user:pass@example.org","relative-path","https://example.org/\ninvalid"})Check(!snapshot.TryRefresh(()=>source)&&snapshot.LastAddress=="https://example.org/app#guardado","Invalid/cleanup source cannot overwrite snapshot");Check(!snapshot.TryRefresh(()=>throw new InvalidOperationException("Native source unavailable"))&&snapshot.LastAddress=="https://example.org/app#guardado","Engine failure preserves snapshot");});
Test("Appearance: theme system and contrast priority matrix", () => {
 foreach(var theme in Enum.GetValues<ThemePreference>()) foreach(var dark in new[]{false,true}) foreach(var manual in new[]{false,true}) foreach(var system in new[]{false,true}) {
 var expected=system?AppearancePalette.SystemHighContrast:manual?AppearancePalette.HighContrast:theme==ThemePreference.Dark||theme==ThemePreference.System&&dark?AppearancePalette.Dark:AppearancePalette.Light;
 Check(AppearancePolicy.Resolve(new(){Theme=theme,HighContrast=manual},dark,system).Palette==expected,$"Matrix {theme}/{dark}/{manual}/{system}"); }
});
Test("Appearance: easy mode floor preserves manual preferences and restores them", () => {
 foreach(var scale in new[]{1d,1.25,1.5,2}) {var manual=new BrowserSettings {Theme=ThemePreference.Light,TextScale=scale,HighContrast=true};var easy=manual with {EasyMode=true};var state=AppearancePolicy.Resolve(easy,true,false);Check(state.TextScale==Math.Max(1.25,scale)&&state.EasyMode&&easy.TextScale==scale&&easy.HighContrast,"Effective floor preserves inputs");Check(AppearancePolicy.Resolve(easy with {EasyMode=false},true,false).TextScale==scale,"Turning off restores manual scale");}
});
Test("Appearance: invalid theme and scale fail clearly", () => {
 foreach(var invalid in new[]{new BrowserSettings {Theme=(ThemePreference)99},new(){TextScale=0.99},new(){TextScale=2.01},new(){TextScale=double.NaN},new(){TextScale=double.PositiveInfinity}}) {bool rejected=false;try{AppearancePolicy.Resolve(invalid,false,false);}catch(ArgumentException){rejected=true;}Check(rejected,"Invalid appearance rejected");}
});
Test("Appearance settings: real disk roundtrip legacy defaults and unknown enum preservation", () => {
 var dir=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString());Directory.CreateDirectory(dir);var path=Path.Combine(dir,"settings.json");try {
 var store=new SettingsStore(path);File.WriteAllText(path,"{}");Check(store.Load().Settings is {Theme:ThemePreference.Dark,EasyMode:false},"Legacy defaults");
 var input=new BrowserSettings {Theme=ThemePreference.System,EasyMode=true,TextScale=1,HighContrast=true,SearchProvider=SearchProvider.Google,RestoreSession=true,SessionUrls=["https://example.org"],Bookmarks=[new("Saved","https://example.org")]};Check(store.Save(input)==null,"Save appearance");var result=store.Load().Settings;Check(result.Theme==input.Theme&&result.EasyMode&&result.TextScale==1&&result.HighContrast&&result.SearchProvider==input.SearchProvider&&result.Bookmarks.SequenceEqual(input.Bookmarks)&&result.SessionUrls.SequenceEqual(input.SessionUrls)&&result.PrivacyRules.SequenceEqual(input.PrivacyRules),"Roundtrip preserves unrelated and manual preferences");
 const string bad="{\"Theme\":99,\"EasyMode\":true}";File.WriteAllText(path,bad);Check(store.Load().Error!=null&&store.Save(new())!=null&&File.ReadAllText(path)==bad,"Unknown enum remains untouched");
 } finally {Directory.Delete(dir,true);}
});
int failed=0;
foreach(var t in tests) { try{t.Run();Console.WriteLine("PASS "+t.Name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+t.Name+": "+e.Message);} }
Console.WriteLine($"{tests.Count-failed}/{tests.Count} checks PASS");return failed==0?0:1;
sealed class TestClock : TimeProvider {DateTimeOffset now=new(2026,10,29,0,0,0,TimeSpan.Zero);long timestamp;public override DateTimeOffset GetUtcNow()=>now;public override long TimestampFrequency=>TimeSpan.TicksPerSecond;public override long GetTimestamp()=>timestamp;public void Advance(int seconds){now=now.AddSeconds(seconds);timestamp+=TimeSpan.FromSeconds(seconds).Ticks;}public void RewindUtc(int seconds)=>now=now.AddSeconds(-seconds);}
